	if (!m_goal_dir_valid)
		m_goal_type = (GOAL_TYPE)0;

	SetGoalDir(type, NULL, false);
	m_goal_timer.m_timer = CAiTimer::infinite;
	m_goal_timer.m_period.m_min = CAiTimer::infinite;
