	m_weapon = NULL;
	m_ammo = NULL;
	m_targetVel = CPnt3D::zero;
	m_targetPos = m_targetVel;
	m_lookDirW = CPnt3D::unit_nz;
	m_aimPointW = CPnt3D::zero;
	m_aimDirM = CPnt3D::unit_nz;
